function catalogLines(text){const lines=[];for(let raw of text.replaceAll("\r","").split("\n")){let accepted=true;while(raw.startsWith("$")||raw.startsWith("%")){const match=raw.match(/^([%$])([^$!]+)([$!])(.*)$/);if(!match){accepted=false;break;}const[,marker,name,operator,remainder]=match;raw=remainder;if(marker==="%")continue;if(!ENABLED_INFO_CONDITIONS.has(name)&&!["MAIN_SERVER","RPG_SERVER","ARCADE_SERVER","TEST_SERVER","HALLOWEEN","WINTER_SEASON","XMAS","NEW_YEARS_EVE","DUAL_WIELD","DEMOLITIONIST_IDDC_ONLY","NO_RUST_NO_HYDROXIDE","WIELD_STAFF_RGM","ENABLE_MYCORRHIZA"].includes(name)){accepted=false;break;}const enabled=conditionEnabled(name);if(operator==="$"?!enabled:enabled){accepted=false;break;}}if(accepted)lines.push(raw);}return lines;}
