function parseKinds(text){const result=[],flags=new Set();let current=null;const finish=()=>{if(current&&current.tval!=null&&current.sval!=null)result.push(current);};for(const raw of catalogLines(text)){if(raw.startsWith("N:")){finish();const parts=raw.split(":");current={index:Number(parts[1]),name:parts.slice(2).join(":"),tval:null,sval:null,glyph:null,level:null,cost:0,allocated:false,flags:new Set(),toH:0,toD:0,toA:0};}else if(current&&raw.startsWith("G:"))current.glyph=raw.split(":")[1]||" ";else if(current&&raw.startsWith("I:")){const parts=raw.split(":");current.tval=Number(parts[1]);current.sval=Number(parts[2]);}else if(current&&raw.startsWith("W:")){const parts=raw.split(":");current.level=Number(parts[1]);current.cost=Number(parts[4]);}else if(current&&raw.startsWith("P:")){const parts=raw.split(":");current.toH=Number(parts[3]);current.toD=Number(parts[4]);current.toA=Number(parts[5]);}else if(current&&raw.startsWith("A:"))current.allocated=raw.slice(2).split(":").some(entry=>Number(entry.split("/")[1])>0);else if(current&&raw.startsWith("F:"))splitFlags(raw).forEach(flag=>{current.flags.add(flag);if(!flag.startsWith("XXX"))flags.add(flag);});}finish();return{records:result,flags};}
