async function loadCatalogs(list){const files=new Map([...list].map(file=>[file.name,file])),missing=REQUIRED.filter(name=>!files.has(name));if(missing.length){catalogsReady=false;catalogStatus(`Не найдены: ${missing.join(", ")}`,"error");validateAndRender();return;}try{const parsed=parseCatalogTexts(await Promise.all(REQUIRED.map(name=>files.get(name).text())));features=parsed.features;races=parsed.races;monsterEgos=parsed.monsterEgos;kinds=parsed.kinds;itemEgos=parsed.itemEgos;monsterFlagNames=parsed.monsterFlags;itemFlagNames=parsed.itemFlags;if(!features.size||!races.size||!kinds.length)throw new Error("один из справочников не содержит игровых записей");catalogsReady=true;catalogStatus(`Загружены 5 справочников · ${features.size} terrain · ${races.size} рас · ${kinds.length} предметов`,"ok");populateCatalogControls();render();}catch(error){catalogsReady=false;catalogStatus(`Ошибка чтения: ${error.message}`,"error");validateAndRender();}}
