function kindSupportsQuality(kind,quality){if(kind.tval===45&&kind.sval===5)return false;if(quality==="normal")return true;const armour=[30,31,32,33,34,35,36,37,38],weapons=[15,19,20,21,22,23,24],ammo=[16,17,18];if(armour.includes(kind.tval))return kind.toA>=0;if(weapons.includes(kind.tval))return kind.toH>=0&&kind.toD>=0;if(ammo.includes(kind.tval))return kind.sval!==5;if([6,46].includes(kind.tval))return true;const good=new Map([[45,[31,32,33,34,35,36,37,48,49,52,58,57,28,29,30,40,45,46,53,20,47,54,18,19,17,56]],[39,[2,3,4,100,101,102,104,105,106]],[40,[6,9,10,11,12,15,17,18,19,20,21,22,8,23,25,33,24,34,38,40,31,30]],[55,[17,18,19,22,23,24,25,26,27,28,29,33]],[65,[16,18,19,33,20,21,23,22,12,25,26,27,28,29,3]],[66,[2,3,5,6,7,8,9,10,11,13,18,20,21,23,22,24,25,27,26,28]]]),great=new Map([[45,[31,32,33,34,35,36,37,48,49,52,58,57]],[39,[3,4,100,101,102,104,105,106]],[40,[31,10,11,12,18,19,20,22,8,23,25,24,34,38,40]],[55,[25,19,26,33]],[65,[12,25,29]],[66,[6,7,8,13,20,21,23,22,24,25,27,26,3,5,2,9,10,11,18,28]]]);const special=(quality==="great"?great:good).get(kind.tval);if(special?.includes(kind.sval))return true;if(quality==="good")return kind.cost>=200;if(kind.tval===107)return false;if(kind.tval===111)return kind.cost>20000;if(kind.tval===52)return kind.cost>=20000;return kind.cost>7000;}
