function applyCell(x,y){if(activeLayer==="entrances"){toggleEntrance(x,y,false);return;}const map=model.maps[activeLayer];if(activeTool==="picker"){selectedSymbols[activeLayer]=map[y][x];renderProfiles();return;}map[y][x]=activeTool==="erase"?"_":selectedSymbols[activeLayer];renderGrid();validateAndRender();}
