function resizeTemplate(){const width=Number(ui.width.value),height=Number(ui.height.value);if(!validDimensions(width,height))return showToast("Допустимы размеры до 40×80 с учётом поворота.");const cropped=model.entrances.some(point=>point.x>=width||point.y>=height)||Object.values(model.maps).some(map=>map.some((row,y)=>y>=height?row.some(value=>value!=="_"):row.slice(width).some(value=>value!=="_")));if(cropped&&!confirm("Уменьшение обрежет непустые клетки или входы. Продолжить?")){ui.width.value=model.width;ui.height.value=model.height;return;}checkpoint();for(const key of Object.keys(model.maps)){const next=emptyMap(width,height);for(let y=0;y<Math.min(height,model.height);y++)for(let x=0;x<Math.min(width,model.width);x++)next[y][x]=model.maps[key][y][x];model.maps[key]=next;}model.entrances=model.entrances.filter(point=>point.x<width&&point.y<height);model.width=width;model.height=height;render();}

function parseProfileNumber(value,lineNumber,field){if(!/^\d+$/.test(value))throw new Error(`строка ${lineNumber}: неверное число ${field}`);return Number(value);}
function parseProfileLine(line,lineNumber,profiles,type){
  if(line.length<4||line[3]!==":")throw new Error(`строка ${lineNumber}: неверная директива ${type}`);
  const symbol=line[2];
  if(!validSymbol(symbol))throw new Error(`строка ${lineNumber}: неверный символ профиля`);
  const profile=profiles[symbol]||(profiles[symbol]=type==="M"?emptyMonsterProfile():emptyItemProfile()),tail=line.slice(4);
  if(!tail){if(profile.__empty)throw new Error(`строка ${lineNumber}: повтор пустого профиля`);profile.__empty=true;return;}
  const separator=tail.indexOf(":");
  if(separator<0)throw new Error(`строка ${lineNumber}: поле профиля не имеет значения`);
  const field=tail.slice(0,separator),value=tail.slice(separator+1),seen=profile.__seen||(profile.__seen=new Set());
  if(field!=="flag"&&field!=="only_r_idx"&&seen.has(field))throw new Error(`строка ${lineNumber}: повтор поля ${field}`);
  seen.add(field);
  if(type==="M"){
    if(field==="r_idx")profile.rIdx=parseProfileNumber(value,lineNumber,field);
    else if(field==="flag"){if(!value||profile.flags.includes(value))throw new Error(`строка ${lineNumber}: пустой или повторный flag`);profile.flags.push(value);}
    else if(field==="glyph"){if(!validGlyph(value))throw new Error(`строка ${lineNumber}: неверный glyph`);profile.glyph=value;}
    else if(field==="level"){const values=value.split(":");if(values.length!==2)throw new Error(`строка ${lineNumber}: неверный диапазон level`);profile.level={min:parseProfileNumber(values[0],lineNumber,field),max:parseProfileNumber(values[1],lineNumber,field)};}
    else if(field==="only_r_idx"){const id=parseProfileNumber(value,lineNumber,field);if(profile.onlyRIdx.includes(id))throw new Error(`строка ${lineNumber}: повтор only_r_idx`);profile.onlyRIdx.push(id);}
    else if(field==="ego"){const exact=value.match(/^exact:(\d+)$/);if(exact)profile.ego={mode:"exact",idx:Number(exact[1])};else if(["auto","none","required"].includes(value))profile.ego={mode:value,idx:null};else throw new Error(`строка ${lineNumber}: неверный режим ego`);}
    else throw new Error(`строка ${lineNumber}: неизвестное поле M:${field}`);
  }else{
    if(field==="tval")profile.tval=parseProfileNumber(value,lineNumber,field);
    else if(field==="sval")profile.sval=parseProfileNumber(value,lineNumber,field);
    else if(field==="flag"){if(!value||profile.flags.includes(value))throw new Error(`строка ${lineNumber}: пустой или повторный flag`);profile.flags.push(value);}
    else if(field==="glyph"){if(!validGlyph(value))throw new Error(`строка ${lineNumber}: неверный glyph`);profile.glyph=value;}
    else if(field==="level"){const values=value.split(":");if(values.length!==2)throw new Error(`строка ${lineNumber}: неверный диапазон level`);profile.level={min:parseProfileNumber(values[0],lineNumber,field),max:parseProfileNumber(values[1],lineNumber,field)};}
    else if(field==="quality"){if(!["normal","good","great"].includes(value))throw new Error(`строка ${lineNumber}: неверное качество`);profile.quality=value;}
    else if(field==="ego"){const exact=value.match(/^exact:(\d+)(?::(\d+))?$/);if(exact)profile.ego={mode:"exact",indices:[Number(exact[1]),exact[2]==null?null:Number(exact[2])].filter(id=>id!=null)};else if(["default","required"].includes(value))profile.ego={mode:value,indices:[]};else throw new Error(`строка ${lineNumber}: неверный режим ego`);}
    else throw new Error(`строка ${lineNumber}: неизвестное поле I:${field}`);
  }
}
function stripParserState(profiles){for(const profile of Object.values(profiles)){delete profile.__seen;delete profile.__empty;}}
function parseGameText(text,fileName=null){const lines=text.replaceAll("\r","").split("\n"),terrainProfiles={},monsterProfiles={},itemProfiles={},entrances=[],maps={},seen=new Set(),markers=["DT:","DM:","DI:"];let version=null,code=null,name=null,width=null,height=null,depth=null,weight=null,phase=0,nextMap=0;const orderError=lineNumber=>{throw new Error(`строка ${lineNumber}: директива нарушает порядок секций или повторяется`);};for(let index=0;index<lines.length;index++){const line=lines[index];if(!line||line.startsWith("#"))continue;if(markers.includes(line)){if(line!==markers[nextMap]||phase<3)orderError(index+1);const key={"DT:":"terrain","DM:":"monsters","DI:":"items"}[line],rows=[];for(let row=0;row<height;row++){index++;const value=lines[index];if(value==null||[...value].length!==width)throw new Error(`строка ${index+1}: ширина строки карты должна быть ${width}`);rows.push([...value]);}maps[key]=rows;nextMap++;phase=7;continue;}if(phase===7)orderError(index+1);const fields=line.split(":"),directive=fields[0];switch(directive){case"V":if(phase!==0||fields.length!==2)orderError(index+1);version=Number(fields[1]);phase=1;break;case"N":if(phase!==1||fields.length<3)orderError(index+1);code=fields[1];name=fields.slice(2).join(":");phase=2;break;case"S":if(phase!==2||fields.length!==3)orderError(index+1);width=Number(fields[1]);height=Number(fields[2]);phase=3;break;case"P":if(phase!==3||seen.has(`P:${fields[1]}`))orderError(index+1);seen.add(`P:${fields[1]}`);if(fields[1]==="depth"&&fields.length===4)depth={min:Number(fields[2]),max:Number(fields[3])};else if(fields[1]==="weight"&&fields.length===3)weight=Number(fields[2]);else throw new Error(`строка ${index+1}: неизвестная директива профиля`);break;case"E":if(phase!==3||fields.length!==3)orderError(index+1);entrances.push({x:Number(fields[1]),y:Number(fields[2])});break;case"T":if(phase<3||phase>4||fields.length!==3||fields[1]in terrainProfiles)orderError(index+1);phase=4;terrainProfiles[fields[1]]=Number(fields[2]);break;case"I":if(phase<3||phase>5)orderError(index+1);phase=5;parseProfileLine(line,index+1,itemProfiles,"I");break;case"M":if(phase<3||phase>6)orderError(index+1);phase=6;parseProfileLine(line,index+1,monsterProfiles,"M");break;default:throw new Error(`строка ${index+1}: неизвестная директива «${directive}»`);}}if(version!==1)throw new Error("требуется строка V:1");if(!code||name==null||!width||!height)throw new Error("требуются строки N и S");if(nextMap!==3)throw new Error("требуются карты DT, DM и DI в этом порядке");if(fileName&&fileName.toLowerCase().endsWith(".txt")&&fileName.slice(0,-4)!==code)throw new Error(`имя файла должно быть ${code}.txt`);stripParserState(monsterProfiles);stripParserState(itemProfiles);return normalizeModel({format:2,code,name,width,height,depth,weight,terrainProfiles,monsterProfiles,itemProfiles,maps,entrances:uniqueEntrances(entrances)});}
function legacyProfiles(lines,type){const profiles={};for(const line of lines||[])parseProfileLine(String(line),0,profiles,type);stripParserState(profiles);return profiles;}
function normalizeMonsterProfile(value){const result=emptyMonsterProfile();if(!value)return result;result.rIdx=value.rIdx==null?null:Number(value.rIdx);result.flags=uniqueValues([...(value.flags||[])].map(String));result.glyph=value.glyph==null||value.glyph===""?null:String(value.glyph);result.level=value.level==null?null:{min:Number(value.level.min),max:Number(value.level.max)};result.onlyRIdx=uniqueValues([...(value.onlyRIdx||[])].map(Number));result.ego={mode:String(value.ego?.mode||"auto"),idx:value.ego?.idx==null?null:Number(value.ego.idx)};return result;}
function normalizeItemProfile(value){const result=emptyItemProfile();if(!value)return result;result.tval=value.tval==null?null:Number(value.tval);result.sval=value.sval==null?null:Number(value.sval);result.flags=uniqueValues([...(value.flags||[])].map(String));result.glyph=value.glyph==null||value.glyph===""?null:String(value.glyph);result.level=value.level==null?null:{min:Number(value.level.min),max:Number(value.level.max)};result.quality=String(value.quality||"normal");result.ego={mode:String(value.ego?.mode||"default"),indices:uniqueValues([...(value.ego?.indices||[])].map(Number))};return result;}
function normalizeModel(value){if(!value||![1,2].includes(value.format))throw new Error("неподдерживаемая версия черновика");const result=newModel(String(value.code||""),String(value.name||""),Number(value.width),Number(value.height));if(!validDimensions(result.width,result.height))throw new Error("недопустимый размер шаблона");result.depth=value.depth==null?null:{min:Number(value.depth.min),max:Number(value.depth.max)};result.weight=value.weight==null?null:Number(value.weight);result.terrainProfiles={...(value.terrainProfiles||{})};const monsters=value.monsterProfiles||legacyProfiles(value.entityDefinitions?.monsters,"M"),items=value.itemProfiles||legacyProfiles(value.entityDefinitions?.items,"I");for(const[symbol,profile]of Object.entries(monsters))result.monsterProfiles[symbol]=normalizeMonsterProfile(profile);for(const[symbol,profile]of Object.entries(items))result.itemProfiles[symbol]=normalizeItemProfile(profile);for(const key of["terrain","monsters","items"]){if(!Array.isArray(value.maps?.[key])||value.maps[key].length!==result.height||value.maps[key].some(row=>!Array.isArray(row)||row.length!==result.width))throw new Error(`неверный размер карты ${key}`);result.maps[key]=value.maps[key].map(row=>row.map(symbol=>{const text=String(symbol);if(text!=="_"&&!validSymbol(text))throw new Error(`недопустимый символ карты ${key}`);return text;}));}result.entrances=uniqueEntrances((value.entrances||[]).map(point=>({x:Number(point.x),y:Number(point.y)})));return result;}
function monsterLines(symbol,profile){const prefix=`M:${symbol}:`,lines=[];if(profile.rIdx!=null)lines.push(`${prefix}r_idx:${profile.rIdx}`);profile.flags.forEach(flag=>lines.push(`${prefix}flag:${flag}`));if(profile.glyph!=null)lines.push(`${prefix}glyph:${profile.glyph}`);if(profile.level)lines.push(`${prefix}level:${profile.level.min}:${profile.level.max}`);profile.onlyRIdx.forEach(id=>lines.push(`${prefix}only_r_idx:${id}`));if(profile.ego.mode!=="auto")lines.push(`${prefix}ego:${profile.ego.mode}${profile.ego.mode==="exact"?`:${profile.ego.idx}`:""}`);if(!lines.length)lines.push(prefix);return lines;}
function itemLines(symbol,profile){const prefix=`I:${symbol}:`,lines=[];if(profile.tval!=null)lines.push(`${prefix}tval:${profile.tval}`);if(profile.sval!=null)lines.push(`${prefix}sval:${profile.sval}`);profile.flags.forEach(flag=>lines.push(`${prefix}flag:${flag}`));if(profile.glyph!=null)lines.push(`${prefix}glyph:${profile.glyph}`);if(profile.level)lines.push(`${prefix}level:${profile.level.min}:${profile.level.max}`);if(profile.quality!=="normal")lines.push(`${prefix}quality:${profile.quality}`);if(profile.ego.mode!=="default")lines.push(`${prefix}ego:${profile.ego.mode}${profile.ego.mode==="exact"?`:${profile.ego.indices.join(":")}`:""}`);if(!lines.length)lines.push(prefix);return lines;}
function gameText(){const lines=["# TomeNET room template generated by tools/room_template_editor","# In DT maps '_' is transparent and leaves the original level cell unchanged.","# In DM and DI maps '_' means that no monster or item is placed.","V:1",`N:${model.code}:${model.name}`,`S:${model.width}:${model.height}`];if(model.depth)lines.push(`P:depth:${model.depth.min}:${model.depth.max}`);if(model.weight!=null)lines.push(`P:weight:${model.weight}`);model.entrances.forEach(point=>lines.push(`E:${point.x}:${point.y}`));Object.entries(model.terrainProfiles).sort().forEach(([symbol,fIdx])=>lines.push(`T:${symbol}:${fIdx}`));Object.entries(model.itemProfiles).sort().forEach(([symbol,profile])=>lines.push(...itemLines(symbol,profile)));Object.entries(model.monsterProfiles).sort().forEach(([symbol,profile])=>lines.push(...monsterLines(symbol,profile)));lines.push("DT:",...model.maps.terrain.map(row=>row.join("")),"DM:",...model.maps.monsters.map(row=>row.join("")),"DI:",...model.maps.items.map(row=>row.join("")),"");return lines.join("\n");}
function download(name,text,type){const link=document.createElement("a");link.href=URL.createObjectURL(new Blob([text],{type}));link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),0);setDirty(false);}
function showToast(message){ui.toast.textContent=message;ui.toast.classList.add("visible");setTimeout(()=>ui.toast.classList.remove("visible"),2600);}
function oriented(source,mirrored,rotations){let maps=Object.fromEntries(Object.entries(source.maps).map(([key,map])=>[key,map.map(row=>[...row])])),entrances=source.entrances.map(point=>({...point})),width=source.width,height=source.height;if(mirrored){Object.values(maps).forEach(map=>map.forEach(row=>row.reverse()));entrances=entrances.map(point=>({x:width-1-point.x,y:point.y}));}for(let turn=0;turn<rotations;turn++){for(const key of Object.keys(maps))maps[key]=Array.from({length:width},(_,y)=>Array.from({length:height},(_,x)=>maps[key][height-1-x][y]));entrances=entrances.map(point=>({x:height-1-point.y,y:point.x}));[width,height]=[height,width];}return{maps,entrances,width,height};}
function showOrientations(){ui.orientationGallery.replaceChildren();for(const mirrored of[false,true])for(let rotation=0;rotation<4;rotation++){const view=oriented(model,mirrored,rotation),card=document.createElement("section"),heading=document.createElement("h3"),grid=document.createElement("div"),entrances=new Set(view.entrances.map(pointKey));card.className="orientation-card";heading.textContent=`${mirrored?"Отражение + ":""}${rotation*90}° · ${view.width}×${view.height}`;grid.className="mini-grid";grid.style.gridTemplateColumns=`repeat(${view.width}, 16px)`;for(let y=0;y<view.height;y++)for(let x=0;x<view.width;x++){const terrain=view.maps.terrain[y][x],monster=view.maps.monsters[y][x],item=view.maps.items[y][x],cell=document.createElement("span"),entities=[monster!=="_"?`M:${monster}`:"",item!=="_"?`I:${item}`:""].filter(Boolean).join(" ");cell.className="mini-cell";cell.textContent=terrain;cell.title=`(${x},${y}) · T:${terrain}${entities?` · ${entities}`:""}`;if(entities){cell.classList.add("entities");cell.dataset.entities=entities;}if(entrances.has(`${x},${y}`))cell.classList.add("entrance");grid.append(cell);}card.append(heading,grid);ui.orientationGallery.append(card);}ui.orientationDialog.showModal();}

ui.catalogInput.addEventListener("change",()=>loadCatalogs(ui.catalogInput.files));
for(const control of[ui.serverProfile,ui.seasonHalloween,ui.seasonXmas])control.addEventListener("change",()=>{if(ui.catalogInput.files.length)loadCatalogs(ui.catalogInput.files);});
$("create-button").addEventListener("click",()=>{const width=Number($("new-width").value),height=Number($("new-height").value);if(!validDimensions(width,height))return showToast("Допустимы размеры до 40×80 с учётом поворота.");model=newModel($("new-code").value.trim(),$("new-name").value,width,height);undoStack=[];redoStack=[];setDirty(true);render();});
$("template-input").addEventListener("change",async event=>{const file=event.target.files[0];if(!file)return;try{model=file.name.toLowerCase().endsWith(".json")?normalizeModel(JSON.parse(await file.text())):parseGameText(await file.text(),file.name);undoStack=[];redoStack=[];setDirty(false);render();}catch(error){showToast(`Не удалось открыть файл: ${error.message}`);}finally{event.target.value="";}});
for(const[element,key]of[[ui.code,"code"],[ui.name,"name"]])element.addEventListener("change",()=>{if(model[key]===element.value)return;checkpoint();model[key]=element.value;render();});
for(const input of[ui.depthMin,ui.depthMax,ui.weight])input.addEventListener("change",()=>{checkpoint();const min=optionalNumber(ui.depthMin.value),max=optionalNumber(ui.depthMax.value);model.depth=min==null&&max==null?null:{min,max};model.weight=optionalNumber(ui.weight.value);render();});
$("resize-button").addEventListener("click",resizeTemplate);$("add-terrain").addEventListener("click",()=>openTerrainDialog());$("add-monster").addEventListener("click",()=>openMonsterDialog());$("add-item").addEventListener("click",()=>openItemDialog());ui.terrainFeature.addEventListener("change",updateTerrainDetails);$("terrain-cancel").addEventListener("click",()=>ui.terrainDialog.close());document.querySelectorAll("[data-close]").forEach(button=>button.addEventListener("click",()=>$(button.dataset.close).close()));
ui.terrainForm.addEventListener("submit",event=>{event.preventDefault();const symbol=ui.terrainSymbol.value,fIdx=Number(ui.terrainFeature.value);if(!validSymbol(symbol))return showToast("Нужен один печатный ASCII-символ, кроме _, : и пробела.");if(!editingProfile&&symbol in model.terrainProfiles)return showToast("Этот символ уже определён.");if(terrainRejection(features.get(fIdx)))return showToast("Выбранный рельеф запрещён.");checkpoint();model.terrainProfiles[symbol]=fIdx;selectedSymbols.terrain=symbol;ui.terrainDialog.close();render();});
ui.monsterForm.addEventListener("submit",event=>{event.preventDefault();const symbol=ui.monsterSymbol.value;if(!validSymbol(symbol)||(!editingProfile&&symbol in model.monsterProfiles))return showToast("Неверный или занятый символ профиля.");const min=optionalNumber(ui.monsterLevelMin.value),max=optionalNumber(ui.monsterLevelMax.value),mode=ui.monsterEgoMode.value;checkpoint();model.monsterProfiles[symbol]={rIdx:optionalNumber(ui.monsterRIdx.value),flags:flagList(ui.monsterFlags.value),glyph:ui.monsterGlyph.value||null,level:min==null&&max==null?null:{min,max},onlyRIdx:numberList(ui.monsterOnly.value),ego:{mode,idx:mode==="exact"?optionalNumber(ui.monsterEgoIdx.value):null}};selectedSymbols.monsters=symbol;ui.monsterDialog.close();render();});
ui.itemForm.addEventListener("submit",event=>{event.preventDefault();const symbol=ui.itemSymbol.value;if(!validSymbol(symbol)||(!editingProfile&&symbol in model.itemProfiles))return showToast("Неверный или занятый символ профиля.");const min=optionalNumber(ui.itemLevelMin.value),max=optionalNumber(ui.itemLevelMax.value),mode=ui.itemEgoMode.value;checkpoint();model.itemProfiles[symbol]={tval:optionalNumber(ui.itemTval.value),sval:optionalNumber(ui.itemSval.value),flags:flagList(ui.itemFlags.value),glyph:ui.itemGlyph.value||null,level:min==null&&max==null?null:{min,max},quality:ui.itemQuality.value,ego:{mode,indices:mode==="exact"?[optionalNumber(ui.itemEgo1.value),optionalNumber(ui.itemEgo2.value)].filter(value=>value!=null):[]}};selectedSymbols.items=symbol;ui.itemDialog.close();render();});
document.querySelectorAll(".layer").forEach(button=>button.addEventListener("click",()=>{activeLayer=button.dataset.layer;document.querySelectorAll(".layer").forEach(item=>item.classList.toggle("active",item===button));ui.tools.hidden=activeLayer==="entrances";renderGrid();}));
document.querySelectorAll(".tool").forEach(button=>button.addEventListener("click",()=>{activeTool=button.dataset.tool;document.querySelectorAll(".tool").forEach(item=>item.classList.toggle("active",item===button));}));
function pointerCell(event){return document.elementFromPoint?.(event.clientX,event.clientY)?.closest?.(".cell")||event.target.closest?.(".cell");}
function finishDrawing(){if(!drawing)return;if(rectangleStart&&rectangleEnd)fillRectangle(rectangleStart,rectangleEnd);drawing=false;rectangleStart=null;rectangleEnd=null;if(drawingPointerId!=null&&ui.grid.hasPointerCapture?.(drawingPointerId))ui.grid.releasePointerCapture(drawingPointerId);drawingPointerId=null;render();}
ui.grid.addEventListener("pointerdown",event=>{const cell=event.target.closest(".cell");if(!cell)return;const point={x:Number(cell.dataset.x),y:Number(cell.dataset.y)};if(activeLayer==="entrances")return toggleEntrance(point.x,point.y);if(activeTool==="picker")return applyCell(point.x,point.y);checkpoint();drawing=true;drawingPointerId=event.pointerId;ui.grid.setPointerCapture?.(event.pointerId);if(activeTool==="rectangle"){rectangleStart=point;rectangleEnd=point;renderGrid();}else applyCell(point.x,point.y);});
ui.grid.addEventListener("pointermove",event=>{if(!drawing||event.pointerId!==drawingPointerId)return;if(event.buttons===0)return finishDrawing();const cell=pointerCell(event);if(!cell)return;const point={x:Number(cell.dataset.x),y:Number(cell.dataset.y)};if(activeTool==="rectangle"){rectangleEnd=point;renderGrid();}else applyCell(point.x,point.y);});
ui.grid.addEventListener("pointerup",event=>{if(event.pointerId===drawingPointerId)finishDrawing();});ui.grid.addEventListener("pointercancel",finishDrawing);ui.grid.addEventListener("lostpointercapture",finishDrawing);window.addEventListener("blur",finishDrawing);ui.undo.addEventListener("click",undo);ui.redo.addEventListener("click",redo);
window.addEventListener("keydown",event=>{if(!(event.ctrlKey||event.metaKey)||event.key.toLowerCase()!=="z")return;event.preventDefault();event.shiftKey?redo():undo();});
$("save-draft").addEventListener("click",()=>download(`${model.code||"room_template"}.json`,`${JSON.stringify(model,null,2)}\n`,"application/json"));ui.exportButton.addEventListener("click",()=>download(`${model.code}.txt`,gameText(),"text/plain;charset=utf-8"));$("orientations").addEventListener("click",showOrientations);window.addEventListener("beforeunload",event=>{if(!dirty)return;event.preventDefault();event.returnValue="";});
